          ]
        },
        {
          "proposicao": "Segundo a conclusão relatada, metodologias e serviços de suporte à decisão existentes no mundo são relativamente novos e sua aplicação em projetos no Brasil necessitaria de adequação ao cenário brasileiro.",
          "trechos": [
            "E0cd8f22d53fdc052:700:1393"
          ],
          "condicoes": [
            "conforme a conclusão do estudo após análise de artigos e projetos internacionais",
            "para aplicação em projetos de descomissionamento no Brasil"
